#!/usr/bin/env python3
"""Compare all district rows under the same location attribution rules."""
import csv
import hashlib
import html
import json
from collections import defaultdict
from pathlib import Path

ROOT=Path(__file__).resolve().parent
STATIC=ROOT.parent/'open-data-visualization/static/nep-preview'


def build():
    files=[STATIC/'congress-data.json',ROOT/'analysis_output/congress_leg_insertions.json',ROOT/'analysis_output/congress_geographic_attribution_db_3rd.json',ROOT/'analysis_output/hb_nep_comparison_3rd.csv']
    totals=json.loads(files[0].read_text());additions={r['district']:r for r in json.loads(files[1].read_text())['districts']}
    attribution=defaultdict(list)
    for r in json.loads(files[2].read_text())['projects']:
        if r['status']=='unique' and len(r['districts'])==1:attribution[r['districts'][0]].append(r)
    with files[3].open() as f:comparison={r['hgab_id']:r for r in csv.DictReader(f)}
    rows=[]
    for t in totals['strict']:
        district=t['district'];projects=attribution[district];a=additions[district]
        if len(projects)!=t['lineItems'] or sum(r['amountPesos'] for r in projects)!=t['totalPesos']:raise ValueError('Benchmark attribution does not reconcile')
        increases=[comparison[r['id']] for r in projects if comparison[r['id']]['paired_one_to_one']=='True' and int(comparison[r['id']]['amount_delta_pesos'])>0]
        rows.append({'district':district,'representative':t['representative'],'strictHGABLines':t['lineItems'],'strictHGABPesos':t['totalPesos'],
                     'potentialInsertionLines':a['candidateLines'],'potentialInsertionPesos':a['candidateAllocationPesos'],
                     'candidateShareOfAttributedHGAB':a['candidateAllocationPesos']/t['totalPesos'] if t['totalPesos'] else None,
                     'retainedIncreaseLines':len(increases),'retainedIncreasePesos':sum(int(r['amount_delta_pesos']) for r in increases)})
    if sum(r['potentialInsertionLines'] for r in rows)!=sum(r['candidateLines'] for r in additions.values()):raise ValueError('Benchmark insertion counts do not reconcile')
    from build_appropriations_comparison import enrich_rows
    committee=enrich_rows(rows)
    files.extend([ROOT/'analysis_output/appropriations_roster.json', ROOT/'analysis_output/house_leadership_roles.json'])
    (STATIC/'house-leadership-roles.json').write_bytes((ROOT/'analysis_output/house_leadership_roles.json').read_bytes())
    document={'committeeRoster':committee, 'scope':'DPWH HGAB 3rd reading; all roster LEG rows, strict project geography only. Not a ranking of wrongdoing or personal receipts.',
              'comparisonPolicy':'Any district can be selected for comparison. Committee membership is a sourced classification, not a normal budget or evidence of misconduct.',
              'summary':{'districts':len(rows),'totalStrictLines':sum(r['strictHGABLines'] for r in rows)},
              'rows':rows,'sources':[{'file':p.name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()} for p in files]}
    for p in [ROOT/'analysis_output/congress_benchmark.json',STATIC/'congress-benchmark.json']:p.write_text(json.dumps(document,ensure_ascii=False,indent=2)+'\n')
    return document

def render(document):
    from build_appropriations_comparison import comparison
    committee_comparisons=comparison(document['rows'])
    data=json.dumps(document,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    body='''<p><strong>How to read this:</strong> Each row shows projects we could confidently place in one congressional district. The budget is proposed government spending in that area; it is not money paid to its representative. Possible additions are HGAB projects without a selected NEP match. A missing match still needs source review.</p><p>All 254 district rows in the local roster use the same strict HGAB attribution rules. Party-list representatives have no geographic LEG district in this view. The committee filter uses mapped elected Appropriations Committee members. Any district can be selected as a comparison value. Committee identities that conflict with the local representative roster stay unresolved. The numbered committee list does not establish absence of ex-officio membership. A reference value is a comparison point, not a normal budget, a legal threshold or a finding of wrongdoing. Districts with no accepted attribution remain in the table; zero accepted lines does not establish zero funding.</p>
<div class="summary-controls"><input id="bench-search" type="search" placeholder="Representative or legislative district" aria-label="Search representatives or districts"><select id="bench-metric" aria-label="What to compare"><option value="potentialInsertionPesos">Budget for possible added projects</option><option value="potentialInsertionLines">Number of possible added projects</option><option value="candidateShareOfAttributedHGAB">Potential insertion share</option><option value="strictHGABPesos">Estimated district budget</option><option value="strictHGABLines">Projects assigned to this district</option><option value="retainedIncreasePesos">Increases on retained lines</option><option value="retainedIncreaseLines">Count of retained lines with increases</option></select><select id="bench-direction" aria-label="Ranking order"><option value="desc">Largest first</option><option value="asc">Smallest first</option></select><select id="bench-coverage" aria-label="Location matching"><option value="all">All district rows</option><option value="positive">Has projects mapped to one district</option><option value="zero">No projects confidently mapped</option></select><select id="bench-additions" aria-label="Potential insertion coverage"><option value="all">Any candidate count</option><option value="positive">With insertion candidates</option><option value="zero">No insertion candidates</option></select><select id="bench-committee" aria-label="Committee roster classification"><option value="all">All committee classifications</option><option value="member">Listed elected committee members</option><option value="not-listed">Not listed · membership unverified</option><option value="identity-review">Committee identity needs review</option></select><select id="bench-bloc" aria-label="Official committee bloc"><option value="all">All bloc labels</option><option value="majority">Listed majority role</option><option value="minority">Listed minority role</option><option value="unspecified">Alignment not specified in roster role</option></select><select id="bench-mode" aria-label="Reference comparison"><option value="all">All representatives</option><option value="above">At least reference value</option><option value="below">Below reference value</option></select><select id="bench-reference" aria-label="Choose a district for comparison" hidden disabled></select><button id="bench-csv" class="export-btn" type="button">Export filtered ranking CSV</button></div>
<p id="bench-reference-values" hidden></p><figure><figcaption id="bench-chart-caption"></figcaption><div id="bench-chart"></div></figure><p id="bench-count" aria-live="polite"></p><div class="evidence-table"><table data-ph-location-identity-source="roster"><thead><tr><th>Filtered rank</th><th>Congressional district</th><th>Representative</th><th>Relevant roles · sourced roster</th><th>Assigned projects</th><th>Estimated district budget</th><th>Possible added projects</th><th>Budget for possible added projects</th><th>Possible additions as % of assigned budget</th><th>Existing projects with increases · count / added budget</th></tr></thead><tbody id="bench-body"></tbody></table></div><div class="summary-controls"><button id="bench-prev" type="button">Previous</button><span id="bench-page"></span><button id="bench-next" type="button">Next</button></div>
<p class="caution">Insertion amounts are part of HGAB totals, not extra money to add to those totals. Increase amounts are deltas on selected retained lines, not insertion allocations. Missing/shared locations are excluded. Insertion share uses only strictly attributed HGAB amounts; incomplete coverage can distort comparisons. Undefined shares sort last and are excluded from numeric reference comparisons.</p><p>The existing all-district potential-additions view provides the underlying project lists and source pages.</p>'''
    body+='<h3>How districts enter this comparison</h3><p>Project location and scope determine attribution. The same source, location and NEP/HGAB matching rules apply to every district. Representative names and sourced roles are added after the allocation totals are calculated; they do not change project inclusion, matching or amounts. No person is assigned a special baseline or risk score.</p><p>The default view includes all district rows. Rankings follow only the budget metric, order and filters shown above; ties use district name order. The graph shows the first 12 filtered districts for budget/count metrics, or all eligible filtered districts for the share plot. No district is selected automatically for the optional comparison. Committee and majority/minority filters describe the sourced roster and do not establish influence over an allocation.</p>'
    script=r'''<script id="congress-benchmark-script">(()=>{const D=__DATA__,rows=D.rows,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),peso=v=>'₱'+Number(v).toLocaleString('en-PH'),fmt=v=>Number(v).toLocaleString('en-PH');let page=0,current=[];
$('bench-reference').innerHTML='<option value="">Choose a comparison district</option>'+[...rows].sort((a,b)=>a.district.localeCompare(b.district)).map(r=>`<option value="${esc(r.district)}">${esc(r.district)}</option>`).join('');
function compact(v){return v>=1e9?'₱'+(v/1e9).toFixed(2)+'B':v>=1e6?'₱'+(v/1e6).toFixed(1)+'M':peso(v)}
function value(r,k){return k==='candidateShareOfAttributedHGAB'?(r[k]===null?'Undefined':(r[k]*100).toFixed(1)+'%'):k.endsWith('Pesos')?peso(r[k]):fmt(r[k])}

function drawChart(list,k){const share=k==='candidateShareOfAttributedHGAB',top=share?list.filter(r=>r[k]!==null&&r.strictHGABPesos>0):list.slice(0,12),max=Math.max(1,...top.map(r=>share?r.strictHGABPesos:r[k])),height=share?350:410;
let content='<path d="M70 40 V290 H970" fill="none" stroke="#536873"/>';if(share){content+='<text x="5" y="50">100%</text><text x="5" y="290">0%</text><text x="70" y="320">Strictly attributed HGAB allocation →</text><text x="5" y="20">Potential insertion share</text>';content+=top.map(r=>`<circle cx="${70+890*r.strictHGABPesos/max}" cy="${290-250*r[k]}" r="4" fill="#087e78" opacity=".8"><title>${esc(r.representative+' / '+r.district+': '+value(r,k)+'; total '+peso(r.strictHGABPesos))}</title></circle>`).join('')}else{const width=900/Math.max(1,top.length);content+=top.map((r,i)=>{const h=245*r[k]/max,x=80+i*width;return `<rect x="${x}" y="${290-h}" width="${Math.max(3,width-14)}" height="${h}" fill="#087e78"><title>${esc(r.representative+' / '+r.district+': '+value(r,k))}</title></rect><text x="${x}" y="${280-h}" font-size="12">${esc(k.endsWith('Pesos')?compact(r[k]):fmt(r[k]))}</text><text transform="translate(${x+5} 310) rotate(35)" font-size="11">${esc(r.district)}</text>`}).join('');content+=`<text x="70" y="20">Highest plotted value: ${esc(value({[k]:Math.max(0,...top.map(r=>r[k]))},k))}</text>`}
$('bench-chart').innerHTML=`<svg class="evidence-graphic" viewBox="0 0 1020 ${height}" role="img" aria-label="Filtered district comparison chart">${content}</svg>`;$('bench-chart-caption').textContent=(share?'All filtered districts · allocation versus candidate share':'First 12 filtered districts in selected ranking order')+' · order follows the selected budget metric and filters';}
function render(){const k=$('bench-metric').value,ref=rows.find(r=>r.district===$('bench-reference').value),mode=$('bench-mode').value,q=$('bench-search').value.toLowerCase(),dir=$('bench-direction').value==='desc'?-1:1;
current=rows.filter(r=>(r.district+' '+r.representative).toLowerCase().includes(q)&&($('bench-bloc').value==='all'||r.committeeBloc===$('bench-bloc').value)&&($('bench-committee').value==='all'||r.committeeStatus===$('bench-committee').value)&&($('bench-coverage').value==='all'||($('bench-coverage').value==='positive'?r.strictHGABLines>0:r.strictHGABLines===0))&&($('bench-additions').value==='all'||($('bench-additions').value==='positive'?r.potentialInsertionLines>0:r.potentialInsertionLines===0))&&(mode==='all'||!ref||mode==='above'&&r[k]!==null&&ref[k]!==null&&r[k]>=ref[k]||mode==='below'&&r[k]!==null&&ref[k]!==null&&r[k]<ref[k]));
current.sort((a,b)=>a[k]===null?(b[k]===null?a.district.localeCompare(b.district):1):b[k]===null?-1:dir*(a[k]-b[k])||a.district.localeCompare(b.district));const pages=Math.max(1,Math.ceil(current.length/20));page=Math.max(0,Math.min(page,pages-1));
const comparing=['above','below'].includes(mode);$('bench-reference-values').hidden=!comparing;$('bench-reference-values').textContent=comparing?(ref?'Comparison chosen by reader: '+ref.district+' · '+value(ref,k):'Choose a district to apply the comparison. All rows remain eligible until you choose one.'):'';$('bench-reference').hidden=!comparing;$('bench-reference').disabled=!comparing;
$('bench-count').textContent=current.length+' of '+rows.length+' district rows match. These ranks describe filtered budget metrics, not wrongdoing.';
$('bench-body').innerHTML=current.slice(page*20,page*20+20).map((r,i)=>`<tr><td>${page*20+i+1}</td><td>${esc(r.district)}</td><td><strong>${esc(r.representative)}</strong></td><td>${esc(r.relevantRoles||'No verified role in this view')}<br>${esc(r.committeeStatus==='member'?'Listed elected member':r.committeeStatus==='identity-review'?'Identity needs review':'Not listed; membership unverified')}<br>Bloc: ${esc(r.committeeBloc)}</td><td>${fmt(r.strictHGABLines)}</td><td>${peso(r.strictHGABPesos)}</td><td>${fmt(r.potentialInsertionLines)}</td><td>${peso(r.potentialInsertionPesos)}</td><td>${value(r,'candidateShareOfAttributedHGAB')}</td><td>${fmt(r.retainedIncreaseLines)} / ${peso(r.retainedIncreasePesos)}</td></tr>`).join('')||'<tr><td colspan="10">No matching districts</td></tr>';$('bench-page').textContent='Page '+(page+1)+' of '+pages;$('bench-prev').disabled=page===0;$('bench-next').disabled=page===pages-1;drawChart(current,k);}
['search','metric','direction','coverage','additions','mode','reference','committee','bloc'].forEach(id=>$('bench-'+id).addEventListener(id==='search'?'input':'change',()=>{page=0;render()}));$('bench-prev').onclick=()=>{page--;render()};$('bench-next').onclick=()=>{page++;render()};
$('bench-csv').onclick=()=>{const cols=['filteredRank','district','representative','strictHGABLines','strictHGABPesos','potentialInsertionLines','potentialInsertionPesos','candidateShareOfAttributedHGAB','retainedIncreaseLines','retainedIncreasePesos','committeeStatus','committeeRole','committeeBloc','relevantRoles','bicamStatus'],quote=v=>'"'+String(v??'').replace(/"/g,'""')+'"',csv=[cols,...current.map((r,i)=>cols.map(c=>c==='filteredRank'?i+1:r[c]))].map(r=>r.map(quote).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='congress-filtered-budget-comparison.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};render();})();</script>'''
    # Initial rows use exactly the default metric and tie ordering. Keep names
    # visible before JavaScript initializes or if scripts are unavailable.
    initial=sorted(document['rows'],key=lambda r:(-r['potentialInsertionPesos'],r['district']))[:20]
    initial_rows=[]
    peso_static=lambda n:'₱'+format(n,',.0f')
    for i,r in enumerate(initial):
        status='Listed elected member' if r['committeeStatus']=='member' else 'Identity needs review' if r['committeeStatus']=='identity-review' else 'Not listed; membership unverified'
        share='Undefined' if r['candidateShareOfAttributedHGAB'] is None else format(r['candidateShareOfAttributedHGAB']*100,'.1f')+'%'
        cells=[str(i+1),html.escape(r['district']),'<strong>'+html.escape(r['representative'])+'</strong>',
               html.escape(r['relevantRoles'] or 'No verified role in this view')+'<br>'+status+'<br>Bloc: '+html.escape(r['committeeBloc']),
               format(r['strictHGABLines'],','),peso_static(r['strictHGABPesos']),format(r['potentialInsertionLines'],','),
               peso_static(r['potentialInsertionPesos']),share,format(r['retainedIncreaseLines'],',')+' / '+peso_static(r['retainedIncreasePesos'])]
        initial_rows.append('<tr>'+''.join('<td>'+c+'</td>' for c in cells)+'</tr>')
    body=body.replace('<tbody id="bench-body"></tbody>','<tbody id="bench-body">'+''.join(initial_rows)+'</tbody>')
    body=body.replace('<p id="bench-count" aria-live="polite"></p>', '<p id="bench-count" aria-live="polite">'+str(len(document['rows']))+' district rows · initial ranking by budget for possible added projects.</p>')
    body+=committee_notes(document,committee_comparisons)
    return body,script.replace('__DATA__',data)


def committee_notes(document, stats):
    meta=document['committeeRoster']; esc=html.escape
    members=[r for r in document['rows'] if r['committeeStatus']=='member']
    low=sorted((r for r in members if r['strictHGABLines']>0),key=lambda r:(r['strictHGABPesos'],r['district']))[:10]
    zeros=[r for r in members if r['strictHGABLines']==0]
    peso=lambda n:'₱'+format(n,',.0f') if n is not None else 'Unavailable'
    def csv_button(label,columns,records):
        import io
        buf=io.StringIO();writer=csv.writer(buf);writer.writerow(columns);writer.writerows(records)
        return '<button class="export-btn" type="button" data-csv="'+esc(buf.getvalue(),quote=True)+'">'+esc(label)+'</button>'
    low_csv=csv_button('Export lowest positive allocations CSV',['district','representative','relevantRoles','committeeBloc','strictHGABLines','strictHGABPesos'],[[r[k] for k in ['district','representative','relevantRoles','committeeBloc','strictHGABLines','strictHGABPesos']] for r in low])
    bloc_csv=csv_button('Export bloc comparison CSV',['bloc','mappedDistricts','noAcceptedAttribution','medianIncludingZerosPesos','medianPositiveOnlyPesos'],[[g,v['districts'],v['noAcceptedAttribution'],v['medianStrictAllocationIncludingZeros'],v['medianStrictAllocationPositiveOnly']] for g,v in stats['blocDescriptiveStatistics'].items()])
    rows=''.join('<tr><td>'+esc(r['district'])+'</td><td>'+esc(r['representative'])+'</td><td>'+esc(r['relevantRoles'])+'</td><td>'+esc(r['committeeBloc'])+'</td><td>'+str(r['strictHGABLines'])+'</td><td>'+peso(r['strictHGABPesos'])+'</td></tr>' for r in low)
    peak=max([r['strictHGABPesos'] for r in low],default=1)
    compact=lambda n:('₱'+format(n/1e9,'.2f')+'B') if n>=1e9 else ('₱'+format(n/1e6,'.1f')+'M')
    bars=''.join(f'<rect x="{40+i*96}" y="{200-170*r["strictHGABPesos"]/peak}" width="60" height="{170*r["strictHGABPesos"]/peak}" fill="{"#b65b09" if r["committeeBloc"]=="minority" else "#087e78"}"><title>{esc(r["representative"])}: {peso(r["strictHGABPesos"])}</title></rect><text x="{40+i*96}" y="{190-170*r["strictHGABPesos"]/peak}" font-size="12">{compact(r["strictHGABPesos"])}</text><text transform="translate({45+i*96},220) rotate(35)" font-size="12">{esc(r["representative"])}</text>' for i,r in enumerate(low))
    group_rows=''.join('<tr><td>'+g+'</td><td>'+str(v['districts'])+'</td><td>'+str(v['noAcceptedAttribution'])+'</td><td>'+peso(v['medianStrictAllocationIncludingZeros'])+'</td><td>'+peso(v['medianStrictAllocationPositiveOnly'])+'</td></tr>' for g,v in stats['blocDescriptiveStatistics'].items())
    highest=stats['metrics']['strictHGABPesos']['highestListedMember'];outside=stats['metrics']['strictHGABPesos']['highestNotListed']
    return ('<h3>Committee roster and relevant roles</h3><p><a href="'+esc(meta['source'])+'">Official House Appropriations roster</a>, indexed snapshot retrieved '+meta['asOf']+': '+str(meta['numberedEntries'])+' numbered entries, '+str(meta['uniqueOfficialNames'])+' distinct names, '+str(meta['mappedDistricts'])+' mapped geographic district identities. Repeated names retain both observed roles and are counted once per district. Unmatched identities, party-list representatives and ex-officio membership are not assigned invented district totals. <a href="appropriations-roster.json">Download the sourced roster and identity decisions</a>.</p>'
    '<p>Role labels are descriptive. A roster title alone does not establish political alignment. The current roster is not a certified historical snapshot at the HGAB reading. The committee filter uses mapped elected members; comparison districts can be chosen from the full roster. Missing geographic attribution and representative-roster conflicts remain visible.</p>'
    '<p>Highest mapped elected committee-member allocation: '+esc(highest['district'])+' · '+peso(highest['strictHGABPesos'])+'. Highest allocation outside the recovered numbered roster: '+esc(outside['district'])+' · '+peso(outside['strictHGABPesos'])+'. Outside this roster does not certify non-membership.</p>'
    '<h3>Committee members with the smallest estimated budgets</h3><p>Ten lowest positive strictly attributed DPWH allocations; zero-match districts are reported separately. Teal = majority or unspecified role; orange = explicitly listed minority role. This is descriptive geographic coverage, not a test of favoritism.</p><figure><svg class="evidence-graphic" style="display:block;width:100%;height:auto;max-height:400px" viewBox="0 0 1030 360" role="img" aria-label="Ten lowest positive committee district allocations">'+bars+'</svg></figure>'+low_csv+'<div class="evidence-table"><table data-ph-location-identity-source="roster"><thead><tr><th>Congressional district</th><th>Representative</th><th>Relevant roles</th><th>Official roster bloc</th><th>Assigned projects</th><th>Estimated district budget</th></tr></thead><tbody>'+rows+'</tbody></table></div>'
    '<h3>Compare official majority and minority roles</h3>'+bloc_csv+'<div class="evidence-table"><table><thead><tr><th>Role classification</th><th>Mapped districts</th><th>No confident location matches</th><th>Middle district budget · including unmatched districts</th><th>Middle district budget · matched districts only</th></tr></thead><tbody>'+group_rows+'</tbody></table></div>'
    '<p>Only two territorial district identities mapped to explicitly listed minority roles. Other minority entries are not given territorial totals without an accepted district identity. This small, incomplete sample cannot establish whether political alignment explains allocations. Majority/minority is a House role designation, not a verified opposition label. Comparisons cover DPWH only, and attribution is incomplete; no causal inference or significance claim is made.</p>'
    '<p>No accepted geographic attribution for '+str(len(zeros))+' mapped committee districts: '+esc('; '.join(r['district'] for r in zeros))+'. These are unresolved funding coverage, not proven zero budgets. Use the classification, coverage, bloc and smallest-first filters above to inspect all rows; CSV exports include roles.</p>'
    '<h3>FY2027 bicameral participation</h3><p>'+esc(meta['bicam']['status'])+' <a href="'+esc(meta['bicam']['source'])+'">The official House statement</a> discusses opening bicam proceedings, but does not identify an appointed delegation. Membership in a different body or participation in a prior-year conference does not establish participation in the FY2027 bicam. Record the formal designation and its date before adding a bicam role.</p><p>Available House leadership labels are descriptive, do not affect rankings, and are not a complete leadership roster. They are sourced separately from the <a href="https://congress.gov.ph/house-members/house-leaders">official House leaders page</a>, indexed snapshot retrieved 2026-10-11. This is not a certified roster at the HGAB reading date. <a href="house-leadership-roles.json">Download sourced role labels, identity mappings and date limits</a>. Geographic allocation does not identify who proposed, approved, received or controlled funds.</p>')

if __name__=='__main__':print(json.dumps(build()['summary'],indent=2))
